**What this code covers**

- Complete microservice framework with service registry, inter-service communication, and health checks
- Service discovery registry (like Consul/Eureka)
- Remove instances that haven't sent heartbeat
- Client-side load balancer
- In real implementation, this would be HTTP/gRPC
- Check circuit breaker state
- Compensate in reverse order
- Log for manual intervention

**Defines:** `ServiceInstance`, `ServiceRegistry`, `LoadBalancer`, `CircuitBreaker`, `Microservice`, `SagaStatus`, `SagaStep`, `Saga`, `SagaOrchestrator`, `create_order()`

### Example 1: Microservices Application Framework

```python
"""
Complete microservice framework with service registry,
inter-service communication, and health checks
"""
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Callable
from datetime import datetime
import threading
import time
import json
import uuid

@dataclass
class ServiceInstance:
    service_name: str
    instance_id: str
    host: str
    port: int
    health_url: str
    metadata: dict = field(default_factory=dict)
    status: str = "UP"
    last_heartbeat: float = field(default_factory=time.time)

class ServiceRegistry:
    """Service discovery registry (like Consul/Eureka)"""

    def __init__(self):
        self.services: Dict[str, Dict[str, ServiceInstance]] = {}
        self.lock = threading.Lock()

    def register(self, instance: ServiceInstance):
        with self.lock:
            if instance.service_name not in self.services:
                self.services[instance.service_name] = {}
            self.services[instance.service_name][instance.instance_id] = instance
            print(f"Registered: {instance.service_name}/{instance.instance_id}")

    def deregister(self, service_name: str, instance_id: str):
        with self.lock:
            if service_name in self.services:
                self.services[service_name].pop(instance_id, None)

    def get_instances(self, service_name: str) -> List[ServiceInstance]:
        with self.lock:
            instances = self.services.get(service_name, {})
            return [i for i in instances.values() if i.status == "UP"]

    def heartbeat(self, service_name: str, instance_id: str):
        with self.lock:
            if service_name in self.services:
                instance = self.services[service_name].get(instance_id)
                if instance:
                    instance.last_heartbeat = time.time()

    def evict_stale(self, timeout_seconds: int = 30):
        """Remove instances that haven't sent heartbeat"""
        now = time.time()
        with self.lock:
            for svc_name, instances in self.services.items():
                stale = [
                    iid for iid, inst in instances.items()
                    if now - inst.last_heartbeat > timeout_seconds
                ]
                for iid in stale:
                    instances[iid].status = "DOWN"
                    print(f"Evicted: {svc_name}/{iid}")

class LoadBalancer:
    """Client-side load balancer"""

    def __init__(self, registry: ServiceRegistry):
        self.registry = registry
        self.round_robin_index: Dict[str, int] = {}

    def get_instance(self, service_name: str) -> Optional[ServiceInstance]:
        instances = self.registry.get_instances(service_name)
        if not instances:
            return None

        idx = self.round_robin_index.get(service_name, 0)
        instance = instances[idx % len(instances)]
        self.round_robin_index[service_name] = idx + 1
        return instance

class CircuitBreaker:
    """Circuit breaker for fault tolerance"""

    def __init__(self, failure_threshold: int = 5, recovery_timeout: int = 30):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.failure_count = 0
        self.last_failure_time = 0
        self.state = "CLOSED"  # CLOSED, OPEN, HALF_OPEN

    def call(self, func: Callable, *args, **kwargs):
        if self.state == "OPEN":
            if time.time() - self.last_failure_time > self.recovery_timeout:
                self.state = "HALF_OPEN"
            else:
                raise Exception("Circuit breaker is OPEN")

        try:
            result = func(*args, **kwargs)
            if self.state == "HALF_OPEN":
                self.state = "CLOSED"
                self.failure_count = 0
            return result
        except Exception as e:
            self.failure_count += 1
            self.last_failure_time = time.time()
            if self.failure_count >= self.failure_threshold:
                self.state = "OPEN"
            raise

class Microservice:
    """Base microservice with built-in registry, health, circuit breaker"""

    def __init__(self, name: str, port: int, registry: ServiceRegistry):
        self.name = name
        self.port = port
        self.registry = registry
        self.load_balancer = LoadBalancer(registry)
        self.circuit_breakers: Dict[str, CircuitBreaker] = {}
        self.instance_id = f"{name}-{uuid.uuid4().hex[:8]}"
        self.handlers: Dict[str, Callable] = {}

        # Register self
        self.registry.register(ServiceInstance(
            service_name=name,
            instance_id=self.instance_id,
            host="localhost",
            port=port,
            health_url=f"/health",
        ))

    def register_handler(self, path: str, handler: Callable):
        self.handlers[path] = handler

    def call_service(self, service_name: str, path: str, data: dict = None):
        """Call another microservice with circuit breaker"""
        if service_name not in self.circuit_breakers:
            self.circuit_breakers[service_name] = CircuitBreaker()

        cb = self.circuit_breakers[service_name]
        instance = self.load_balancer.get_instance(service_name)
        if not instance:
            raise Exception(f"No instances of {service_name} available")

        def _make_call():
            handler = None
            # Simulated inter-service call
            for svc_instances in self.registry.services.values():
                for inst in svc_instances.values():
                    if inst.instance_id == instance.instance_id:
                        # In real implementation, this would be HTTP/gRPC
                        return {"status": "ok", "from": instance.instance_id}
            raise Exception(f"Service {service_name} unreachable")

        return cb.call(_make_call)

# Build microservices
registry = ServiceRegistry()

user_service = Microservice("user-service", 8001, registry)
order_service = Microservice("order-service", 8002, registry)
payment_service = Microservice("payment-service", 8003, registry)

# Inter-service call
result = order_service.call_service("user-service", "/users/123")
print(f"Order service called user service: {result}")

# Check circuit breaker state
print(f"Circuit state: {order_service.circuit_breakers['user-service'].state}")
```

### Example 2: Saga Pattern — Distributed Transaction

```python
"""
Saga Orchestrator: manages distributed transactions
across microservices with compensation on failure
"""
from dataclasses import dataclass, field
from typing import Callable, List, Optional, Tuple
from enum import Enum
import uuid
import time

class SagaStatus(Enum):
    PENDING = "pending"
    RUNNING = "running"
    COMPLETED = "completed"
    COMPENSATING = "compensating"
    FAILED = "failed"

@dataclass
class SagaStep:
    name: str
    action: Callable
    compensation: Callable
    status: str = "pending"
    result: Optional[dict] = None
    error: Optional[str] = None

@dataclass
class Saga:
    saga_id: str
    steps: List[SagaStep]
    status: SagaStatus = SagaStatus.PENDING
    context: dict = field(default_factory=dict)

class SagaOrchestrator:
    """Orchestrates distributed transactions with compensation"""

    def __init__(self):
        self.sagas: dict = {}

    def create_saga(self, steps: List[Tuple[str, Callable, Callable]]) -> Saga:
        saga = Saga(
            saga_id=str(uuid.uuid4()),
            steps=[SagaStep(name=n, action=a, compensation=c) for n, a, c in steps]
        )
        self.sagas[saga.saga_id] = saga
        return saga

    def execute(self, saga: Saga, initial_context: dict = None) -> dict:
        saga.status = SagaStatus.RUNNING
        saga.context = initial_context or {}
        completed_steps = []

        for step in saga.steps:
            try:
                print(f"  → Executing: {step.name}")
                result = step.action(saga.context)
                step.status = "completed"
                step.result = result
                saga.context.update(result or {})
                completed_steps.append(step)
            except Exception as e:
                step.status = "failed"
                step.error = str(e)
                print(f"  ✗ Failed: {step.name} — {e}")

                # Compensate in reverse order
                saga.status = SagaStatus.COMPENSATING
                self._compensate(completed_steps, saga.context)
                saga.status = SagaStatus.FAILED
                return {"status": "failed", "failed_step": step.name, "error": str(e)}

        saga.status = SagaStatus.COMPLETED
        return {"status": "completed", "context": saga.context}

    def _compensate(self, steps: List[SagaStep], context: dict):
        for step in reversed(steps):
            try:
                print(f"  ↩ Compensating: {step.name}")
                step.compensation(context)
                step.status = "compensated"
            except Exception as e:
                print(f"  ⚠ Compensation failed for {step.name}: {e}")
                # Log for manual intervention

# --- Service Actions ---
def create_order(ctx):
    print(f"    Creating order for user {ctx['user_id']}")
    order_id = f"ORD-{uuid.uuid4().hex[:8]}"
    return {"order_id": order_id}

def cancel_order(ctx):
    print(f"    Cancelling order {ctx['order_id']}")

def process_payment(ctx):
    print(f"    Processing payment ${ctx['amount']} for order {ctx['order_id']}")
    if ctx.get("simulate_payment_failure"):
        raise Exception("Payment declined — insufficient funds")
    return {"payment_id": f"PAY-{uuid.uuid4().hex[:8]}"}

def refund_payment(ctx):
    print(f"    Refunding payment {ctx.get('payment_id', 'N/A')}")

def reserve_inventory(ctx):
    print(f"    Reserving inventory for order {ctx['order_id']}")
    return {"reservation_id": f"RES-{uuid.uuid4().hex[:8]}"}

def release_inventory(ctx):
    print(f"    Releasing inventory reservation {ctx.get('reservation_id')}")

def schedule_shipping(ctx):
    print(f"    Scheduling shipment for order {ctx['order_id']}")
    return {"shipment_id": f"SHIP-{uuid.uuid4().hex[:8]}"}

def cancel_shipping(ctx):
    print(f"    Cancelling shipment {ctx.get('shipment_id')}")

# --- Execute Saga ---
orchestrator = SagaOrchestrator()

# Happy path
saga = orchestrator.create_saga([
    ("Create Order", create_order, cancel_order),
    ("Process Payment", process_payment, refund_payment),
    ("Reserve Inventory", reserve_inventory, release_inventory),
    ("Schedule Shipping", schedule_shipping, cancel_shipping),
])

print("=== Happy Path ===")
result = orchestrator.execute(saga, {"user_id": "U123", "amount": 99.99})
print(f"Result: {result}\n")

# Failure path — payment fails, everything compensated
saga2 = orchestrator.create_saga([
    ("Create Order", create_order, cancel_order),
    ("Process Payment", process_payment, refund_payment),
    ("Reserve Inventory", reserve_inventory, release_inventory),
])

print("=== Failure Path ===")
result = orchestrator.execute(saga2, {
    "user_id": "U456", "amount": 999.99,
    "simulate_payment_failure": True
})
print(f"Result: {result}")
