### Example 3: Service Mesh (Sidecar Pattern)

```python
"""
Sidecar proxy — handles cross-cutting concerns for microservices
"""
from dataclasses import dataclass, field
from typing import Dict, Optional, Callable
import time
import random

@dataclass
class RequestContext:
    trace_id: str
    span_id: str
    source_service: str
    target_service: str
    path: str
    method: str
    headers: dict = field(default_factory=dict)

class SidecarProxy:
    """
    Sidecar proxy attached to each microservice (like Envoy/Istio)
    Handles: load balancing, retries, circuit breaking, observability
    """

    def __init__(self, service_name: str):
        self.service_name = service_name
        self.circuit_breakers: Dict[str, dict] = {}
        self.metrics: Dict[str, list] = {}
        self.retry_policy = {"max_retries": 3, "backoff_ms": 100}

    def intercept_outgoing(self, ctx: RequestContext, handler: Callable):
        """Intercept all outgoing requests"""
        start = time.time()

        # 1. Distributed tracing — propagate trace headers
        ctx.headers["X-Trace-ID"] = ctx.trace_id
        ctx.headers["X-Span-ID"] = ctx.span_id
        ctx.headers["X-Source-Service"] = self.service_name

        # 2. Circuit breaker check
        cb = self._get_circuit_breaker(ctx.target_service)
        if cb["state"] == "OPEN":
            if time.time() - cb["last_failure"] > 30:
                cb["state"] = "HALF_OPEN"
            else:
                self._record_metric(ctx, 0, "circuit_open")
                return {"error": "Circuit breaker open", "status": 503}

        # 3. Retry with backoff
        for attempt in range(self.retry_policy["max_retries"]):
            try:
                result = handler(ctx)
                latency = (time.time() - start) * 1000

                # Success — record metric, reset circuit breaker
                if cb["state"] == "HALF_OPEN":
                    cb["state"] = "CLOSED"
                    cb["failures"] = 0
                self._record_metric(ctx, latency, "success")
                return result

            except Exception as e:
                cb["failures"] += 1
                if cb["failures"] >= 5:
                    cb["state"] = "OPEN"
                    cb["last_failure"] = time.time()

                if attempt < self.retry_policy["max_retries"] - 1:
                    backoff = self.retry_policy["backoff_ms"] * (2 ** attempt) / 1000
                    time.sleep(backoff)
                else:
                    latency = (time.time() - start) * 1000
                    self._record_metric(ctx, latency, "failure")
                    return {"error": str(e), "status": 500}

    def intercept_incoming(self, ctx: RequestContext, handler: Callable):
        """Intercept all incoming requests"""
        start = time.time()

        # Rate limiting
        # mTLS verification (in real implementation)
        # Request validation

        result = handler(ctx)
        latency = (time.time() - start) * 1000
        self._record_metric(ctx, latency, "incoming")
        return result

    def _get_circuit_breaker(self, service: str) -> dict:
        if service not in self.circuit_breakers:
            self.circuit_breakers[service] = {
                "state": "CLOSED", "failures": 0, "last_failure": 0
            }
        return self.circuit_breakers[service]

    def _record_metric(self, ctx: RequestContext, latency_ms: float, status: str):
        key = f"{ctx.source_service}->{ctx.target_service}"
        if key not in self.metrics:
            self.metrics[key] = []
        self.metrics[key].append({
            "timestamp": time.time(),
            "latency_ms": latency_ms,
            "status": status,
            "trace_id": ctx.trace_id
        })

    def get_metrics_summary(self) -> dict:
        summary = {}
        for key, records in self.metrics.items():
            latencies = [r["latency_ms"] for r in records if r["status"] == "success"]
            summary[key] = {
                "total_requests": len(records),
                "success_count": sum(1 for r in records if r["status"] == "success"),
                "failure_count": sum(1 for r in records if r["status"] == "failure"),
                "avg_latency_ms": sum(latencies) / len(latencies) if latencies else 0,
                "p99_latency_ms": sorted(latencies)[int(len(latencies) * 0.99)] if latencies else 0
            }
        return summary

# Usage
proxy = SidecarProxy("order-service")

ctx = RequestContext(
    trace_id="trace-abc-123",
    span_id="span-001",
    source_service="order-service",
    target_service="user-service",
    path="/users/123",
    method="GET"
)

def simulated_call(ctx):
    time.sleep(random.uniform(0.01, 0.05))
    return {"user_id": "123", "name": "Alice"}

result = proxy.intercept_outgoing(ctx, simulated_call)
print(f"Result: {result}")
print(f"Metrics: {proxy.get_metrics_summary()}")
```

### Example 4: API Gateway with Request Aggregation

```python
"""
API Gateway that aggregates responses from multiple microservices
into a single response for the frontend
"""
import time
import threading
from typing import Dict, List, Callable
from concurrent.futures import ThreadPoolExecutor, as_completed

class APIGateway:
    """Gateway that fans out requests and aggregates responses"""

    def __init__(self, max_workers: int = 10):
        self.routes: Dict[str, List[dict]] = {}
        self.executor = ThreadPoolExecutor(max_workers=max_workers)

    def register_composite_route(self, path: str, service_calls: List[dict]):
        """
        Register a route that calls multiple services.
        service_calls = [
            {"name": "user", "service": "user-service", "path": "/users/{user_id}"},
            {"name": "orders", "service": "order-service", "path": "/users/{user_id}/orders"},
            {"name": "recommendations", "service": "rec-service", "path": "/users/{user_id}/recs"}
        ]
        """
        self.routes[path] = service_calls

    def handle_request(self, path: str, params: dict, timeout: float = 5.0):
        """Fan out to all services, aggregate responses"""
        service_calls = self.routes.get(path)
        if not service_calls:
            return {"error": "Route not found", "status": 404}

        results = {}
        errors = {}
        futures = {}

        for call in service_calls:
            resolved_path = call["path"].format(**params)
            future = self.executor.submit(
                self._call_service,
                call["service"],
                resolved_path,
                timeout
            )
            futures[future] = call["name"]

        # Collect results as they complete
        for future in as_completed(futures, timeout=timeout):
            name = futures[future]
            try:
                results[name] = future.result()
            except Exception as e:
                errors[name] = str(e)

        return {
            "data": results,
            "errors": errors if errors else None,
            "partial": bool(errors)  # Indicate if some services failed
        }

    def _call_service(self, service: str, path: str, timeout: float):
        """Simulated service call"""
        time.sleep(0.05)  # Simulate network latency
        return {"service": service, "path": path, "data": "mock_response"}

# Usage: Mobile app needs user profile + orders + recommendations in ONE call
gateway = APIGateway()

gateway.register_composite_route("/bff/user-profile", [
    {"name": "user", "service": "user-service", "path": "/users/{user_id}"},
    {"name": "orders", "service": "order-service", "path": "/users/{user_id}/orders"},
    {"name": "recommendations", "service": "rec-service", "path": "/recs/{user_id}"},
])

# Single call from frontend, gateway fans out to 3 services in parallel
result = gateway.handle_request("/bff/user-profile", {"user_id": "123"})
print(f"Aggregated response: {result}")
```

### Example 5: Event-Driven Microservices with CQRS

```python
"""
CQRS (Command Query Responsibility Segregation) pattern
Separate write model from read model, linked by events
"""
from dataclasses import dataclass, field
from datetime import datetime
from typing import Dict, List

@dataclass
class Event:
    event_type: str
    aggregate_id: str
    data: dict
    timestamp: datetime = field(default_factory=datetime.utcnow)

class EventBus:
    """Simple in-process event bus"""
    def __init__(self):
        self.handlers: Dict[str, List] = {}
        self.events: List[Event] = []

    def subscribe(self, event_type: str, handler):
        self.handlers.setdefault(event_type, []).append(handler)

    def publish(self, event: Event):
        self.events.append(event)
        for handler in self.handlers.get(event.event_type, []):
            handler(event)

class WriteModel:
    """
    Command side: handles business logic and writes
    Optimized for writes (normalized database)
    """
    def __init__(self, event_bus: EventBus):
        self.products: Dict[str, dict] = {}
        self.event_bus = event_bus

    def create_product(self, product_id: str, name: str, price: float, category: str):
        if product_id in self.products:
            raise ValueError("Product already exists")

        self.products[product_id] = {
            "id": product_id, "name": name,
            "price": price, "category": category, "stock": 0
        }
        self.event_bus.publish(Event("product_created", product_id, {
            "name": name, "price": price, "category": category
        }))

    def update_stock(self, product_id: str, quantity: int):
        product = self.products.get(product_id)
        if not product:
            raise ValueError("Product not found")
        product["stock"] += quantity
        self.event_bus.publish(Event("stock_updated", product_id, {
            "stock": product["stock"]
        }))

    def update_price(self, product_id: str, new_price: float):
        product = self.products.get(product_id)
        if not product:
            raise ValueError("Product not found")
        old_price = product["price"]
        product["price"] = new_price
        self.event_bus.publish(Event("price_updated", product_id, {
            "old_price": old_price, "new_price": new_price
        }))

class ReadModel:
    """
    Query side: optimized for reads (denormalized views)
    Updated asynchronously from events
    """
    def __init__(self):
        self.product_catalog: Dict[str, dict] = {}      # Full catalog view
        self.products_by_category: Dict[str, list] = {}  # Category index
        self.price_history: Dict[str, list] = {}         # Price tracking

    def on_product_created(self, event: Event):
        self.product_catalog[event.aggregate_id] = {
            "id": event.aggregate_id,
            "name": event.data["name"],
            "price": event.data["price"],
            "category": event.data["category"],
            "stock": 0, "in_stock": False
        }
        cat = event.data["category"]
        self.products_by_category.setdefault(cat, []).append(event.aggregate_id)

    def on_stock_updated(self, event: Event):
        product = self.product_catalog.get(event.aggregate_id)
        if product:
            product["stock"] = event.data["stock"]
            product["in_stock"] = event.data["stock"] > 0

    def on_price_updated(self, event: Event):
        product = self.product_catalog.get(event.aggregate_id)
        if product:
            product["price"] = event.data["new_price"]
        self.price_history.setdefault(event.aggregate_id, []).append({
            "price": event.data["new_price"], "date": event.timestamp.isoformat()
        })

    # Fast queries on denormalized data
    def get_product(self, product_id: str) -> dict:
        return self.product_catalog.get(product_id)

    def get_by_category(self, category: str) -> list:
        ids = self.products_by_category.get(category, [])
        return [self.product_catalog[pid] for pid in ids]

    def get_in_stock(self) -> list:
        return [p for p in self.product_catalog.values() if p["in_stock"]]

# Wire everything together
event_bus = EventBus()
write_model = WriteModel(event_bus)
read_model = ReadModel()

# Subscribe read model to events
event_bus.subscribe("product_created", read_model.on_product_created)
event_bus.subscribe("stock_updated", read_model.on_stock_updated)
event_bus.subscribe("price_updated", read_model.on_price_updated)

# Commands (writes)
write_model.create_product("P1", "Laptop", 999.99, "electronics")
write_model.create_product("P2", "Mouse", 29.99, "electronics")
write_model.update_stock("P1", 50)
write_model.update_price("P1", 899.99)

# Queries (reads) — from denormalized read model
print("Product:", read_model.get_product("P1"))
print("Electronics:", read_model.get_by_category("electronics"))
print("In stock:", read_model.get_in_stock())
print("Price history:", read_model.price_history["P1"])
```
